+            activities[i] = new Activity(start[i], finish[i]);
+        }
+        return activities;
+    }
+
+    private static final class Activity {
+        private final int start;
+        private final int finish;
+
+        private Activity(int start, int finish) {
+            this.start = start;
+            this.finish = finish;
+        }
+    }
